package com.cloudinfra.sdk.http;

import java.io.*;
import java.net.Socket;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * MultiTenantHttpProxy - Routes requests to backend services with tenant isolation.
 * Implements connection pooling and request forwarding for the cloud SDK.
 */
public class MultiTenantHttpProxy {

    private final Map<String, ConnectionPool> tenantPools = new ConcurrentHashMap<>();
    private final TenantRegistry tenantRegistry;
    private final RequestSanitizer sanitizer;

    public MultiTenantHttpProxy(TenantRegistry registry) {
        this.tenantRegistry = registry;
        this.sanitizer = new RequestSanitizer();
    }

    public HttpResponse forwardRequest(String tenantId, HttpRequest request) throws IOException {
        if (!tenantRegistry.isValidTenant(tenantId)) {
            return HttpResponse.forbidden("Invalid tenant");
        }

        // Sanitize and normalize the request before forwarding
        HttpRequest sanitized = sanitizer.sanitize(request, tenantId);

        ConnectionPool pool = tenantPools.computeIfAbsent(tenantId,
            id -> new ConnectionPool(tenantRegistry.getBackendHost(id),
                                     tenantRegistry.getBackendPort(id)));

        Socket conn = pool.acquire();
        try {
            writeRequest(conn.getOutputStream(), sanitized);
            return readResponse(conn.getInputStream());
        } finally {
            pool.release(conn);
        }
    }

    private void writeRequest(OutputStream out, HttpRequest request) throws IOException {
        StringBuilder headerBlock = new StringBuilder();
        headerBlock.append(request.getMethod()).append(" ")
                   .append(request.getPath()).append(" HTTP/1.1\r\n");

        for (Map.Entry<String, String> header : request.getHeaders().entrySet()) {
            // Defense-in-depth: never emit a header containing CR/LF, which
            // would allow header/response splitting or injection of framing headers.
            String name = header.getKey();
            String value = header.getValue();
            if (HeaderValidator.containsControlChars(name) || HeaderValidator.containsControlChars(value)) {
                throw new IOException("Illegal control characters in header: " + name);
            }
            headerBlock.append(name).append(": ")
                       .append(value).append("\r\n");
        }
        headerBlock.append("\r\n");

        byte[] headerBytes = headerBlock.toString().getBytes(StandardCharsets.ISO_8859_1);
        out.write(headerBytes);

        if (request.getBody() != null) {
            out.write(request.getBody());
        }
        out.flush();
    }

    private HttpResponse readResponse(InputStream in) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.ISO_8859_1));
        String statusLine = reader.readLine();
        Map<String, String> headers = new LinkedHashMap<>();
        String line;
        while ((line = reader.readLine()) != null && !line.isEmpty()) {
            int colon = line.indexOf(':');
            if (colon > 0) {
                headers.put(line.substring(0, colon).trim().toLowerCase(),
                           line.substring(colon + 1).trim());
            }
        }
        return new HttpResponse(statusLine, headers, null);
    }
}

/**
 * Utility for detecting characters that must never appear in outbound HTTP
 * header names or values (CR, LF and other control chars) to prevent
 * CRLF/header injection (CWE-113).
 */
class HeaderValidator {
    static boolean containsControlChars(String s) {
        if (s == null) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '\r' || c == '\n' || c == '\0') {
                return true;
            }
        }
        return false;
    }
}

class RequestSanitizer {

    private static final Set<String> HOP_BY_HOP = Set.of(
        "connection", "keep-alive", "proxy-authenticate",
        "proxy-authorization", "te", "trailer", "upgrade"
    );

    public HttpRequest sanitize(HttpRequest request, String tenantId) {
        Map<String, String> cleanHeaders = new LinkedHashMap<>();
        String contentLength = null;
        String transferEncoding = null;

        for (Map.Entry<String, String> entry : request.getHeaders().entrySet()) {
            String key = entry.getKey().trim().toLowerCase();
            String value = entry.getValue().trim();

            // Drop any header whose name or value contains control chars to
            // prevent CRLF/header injection (CWE-113).
            if (HeaderValidator.containsControlChars(entry.getKey())
                    || HeaderValidator.containsControlChars(entry.getValue())) {
                continue;
            }

            // Remove hop-by-hop headers
            if (HOP_BY_HOP.contains(key)) {
                continue;
            }

            if (key.equals("content-length")) {
                contentLength = value;
            } else if (key.equals("transfer-encoding")) {
                transferEncoding = value;
            } else {
                cleanHeaders.put(entry.getKey(), value);
            }
        }

        // Resolve ambiguity: if both CL and TE are present, reject the request
        // to prevent request smuggling (RFC 7230 S3.3.3 item 3)
        byte[] body = request.getBody();
        if (transferEncoding != null && contentLength != null) {
            // Both present - this is ambiguous and potentially malicious
            // Strip both and recompute Content-Length from actual body
            int actualLength = body != null ? body.length : 0;
            cleanHeaders.put("Content-Length", String.valueOf(actualLength));
        } else if (transferEncoding != null) {
            // Only allow chunked, reject other TE values
            if ("chunked".equalsIgnoreCase(transferEncoding.trim())) {
                cleanHeaders.put("Transfer-Encoding", "chunked");
            } else {
                // Unknown TE - fall back to Content-Length from body
                int actualLength = body != null ? body.length : 0;
                cleanHeaders.put("Content-Length", String.valueOf(actualLength));
            }
        } else if (contentLength != null) {
            // Validate content-length matches actual body
            if (ContentLengthCalculator.validateContentLength(contentLength, body)) {
                cleanHeaders.put("Content-Length", contentLength);
            } else {
                // Mismatch - use actual body length
                int actualLength = body != null ? body.length : 0;
                cleanHeaders.put("Content-Length", String.valueOf(actualLength));
            }
        }

        // Add tenant isolation header - validate to avoid injecting extra headers.
        if (HeaderValidator.containsControlChars(tenantId)) {
            throw new IllegalArgumentException("Illegal control characters in tenantId");
        }
        cleanHeaders.put("X-Tenant-Id", tenantId);
        cleanHeaders.put("X-Forwarded-By", "cloud-sdk-proxy");
        String hostValue = request.getHeaders().getOrDefault("Host", "localhost");
        if (HeaderValidator.containsControlChars(hostValue)) {
            hostValue = "localhost";
        }
        cleanHeaders.put("Host", hostValue);

        return new HttpRequest(request.getMethod(), request.getPath(), cleanHeaders, body);
    }
}

class ContentLengthCalculator {
    /**
     * Computes the effective content length considering encoding.
     * For chunked TE, returns -1 (streaming).
     * For identity encoding, returns byte count of body.
     */
    public static int computeEffectiveLength(byte[] body, String transferEncoding) {
        if (transferEncoding != null && transferEncoding.toLowerCase().contains("chunked")) {
            return -1; // streaming
        }
        return body != null ? body.length : 0;
    }

    /**
     * Validates that a Content-Length value is consistent with the body.
     * Returns true if the declared length matches the actual body length.
     */
    public static boolean validateContentLength(String declaredLength, byte[] body) {
        try {
            int declared = Integer.parseInt(declaredLength.trim());
            int actual = body != null ? body.length : 0;
            return declared == actual;
        } catch (NumberFormatException e) {
            return false;
        }
    }
}

class HttpRequest {
    private final String method;
    private final String path;
    private final Map<String, String> headers;
    private final byte[] body;

    public HttpRequest(String method, String path, Map<String, String> headers, byte[] body) {
        this.method = method;
        this.path = path;
        this.headers = headers;
        this.body = body;
    }

    public String getMethod() { return method; }
    public String getPath() { return path; }
    public Map<String, String> getHeaders() { return headers; }
    public byte[] getBody() { return body; }
}

class HttpResponse {
    private final String statusLine;
    private final Map<String, String> headers;
    private final byte[] body;

    public HttpResponse(String statusLine, Map<String, String> headers, byte[] body) {
        this.statusLine = statusLine;
        this.headers = headers;
        this.body = body;
    }

    public static HttpResponse forbidden(String msg) {
        return new HttpResponse("HTTP/1.1 403 Forbidden",
            Map.of("Content-Type", "text/plain"), msg.getBytes(StandardCharsets.UTF_8));
    }

    public String getStatusLine() { return statusLine; }
    public Map<String, String> getHeaders() { return headers; }
    public byte[] getBody() { return body; }
}

class ConnectionPool {
    private final String host;
    private final int port;
    private final Deque<Socket> available = new ArrayDeque<>();

    public ConnectionPool(String host, int port) {
        this.host = host;
        this.port = port;
    }

    public synchronized Socket acquire() throws IOException {
        Socket s = available.pollFirst();
        if (s != null && !s.isClosed()) return s;
        return new Socket(host, port);
    }

    public synchronized void release(Socket s) {
        if (!s.isClosed()) available.offerLast(s);
    }
}

interface TenantRegistry {
    boolean isValidTenant(String tenantId);
    String getBackendHost(String tenantId);
    int getBackendPort(String tenantId);
}
